package main

import (
	"encoding/base64"
	"testing"
	"time"
)

func TestValidateAppleAttestation(t *testing.T) {
	// Use a fixed time that falls within the certificate's validity period
	// The certificate is valid from 2024-04-17 to 2024-04-20
	fixedTime := time.Date(2024, 4, 18, 12, 0, 0, 0, time.UTC)
	fixedTime2 := time.Date(2025, 6, 28, 07, 56, 0, 0, time.UTC)
	// Test cases
	tests := []struct {
		name              string
		attestationObj    string
		clientDataJSON    string
		challenge         string
		keyID             string
		expectedErrorText string
		teamId            string
		bundleId          string
		time              time.Time
	}{
		{
			name:              "Valid attestation object",
			attestationObj:    "",
			challenge:         base64.StdEncoding.EncodeToString([]byte("test_server_challenge")),
			keyID:             "bSrEhF8TIzIvWSPwvZ0i2+UOBre4ASH84rK15m6emNY=",
			expectedErrorText: "",
			teamId:            "0352187391",
			bundleId:          "com.apple.example_app_attest",
			time:              fixedTime,
		},
		{
			name:              "Zenobia attestation",
			attestationObj:    "",
			challenge:         "dbajNNz57GPY0HyBJRuaNsRfY0EvwX7BeQ5CIvl1JyY=",
			keyID:             "DNKEcsR4EXKmeSqpj/iX7MkusgSz66wCFW3kKKLvdic=",
			expectedErrorText: "",
			teamId:            "XZAH4FVXK7",
			bundleId:          "zenobia.Zenobia",
			time:              fixedTime2,
		},
	}

	// Run tests
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := ValidateAppleAttestation(tt.attestationObj, tt.challenge, tt.keyID, tt.teamId, tt.bundleId, tt.clientDataJSON, tt.time)

			// Check if error is as expected
			if tt.expectedErrorText != "" {
				if err == nil {
					t.Errorf("Expected error containing %q, got nil", tt.expectedErrorText)
					return
				}
				// if errMsg := err.Error(); errMsg == "" || !contains(errMsg, tt.expectedErrorText) {
				// 	t.Errorf("Expected error containing %q, got %q", tt.expectedErrorText, errMsg)
				// }
			} else if err != nil {
				t.Errorf("Expected no error, got %v", err)
			}
		})
	}
}
